def matches(self, value: Decimal) -> bool:
    """
    Evaluate if value matches this criterion
    Pure business logic - no side effects
    """
    if self.operator == "<":
        return value < self.threshold
    elif self.operator == ">":
        return value > self.threshold
    elif self.operator == "==":
        return value == self.threshold
    elif self.operator == "<=":
        return value <= self.threshold
    elif self.operator == ">=":
        return value >= self.threshold
    return False

